"use client";

// Registers our locally-bundled Iconify icons at module load so every
// <Icon icon="solar:..." /> renders instantly with ZERO network requests to
// api.iconify.design / api.simplesvg.com / api.unisvg.com.
//
// The bundle is generated by scripts/generate-icon-bundle.mjs — re-run it after
// adding new icons. Registration happens at import time (module scope) so icons
// are available before first paint, not after an effect fires.
import { addCollection } from "@iconify/react";
import { iconBundle } from "@/lib/iconify-bundle";

let registered = false;
if (!registered) {
  for (const collection of iconBundle) {
    addCollection(collection);
  }
  registered = true;
}

export default function IconProvider() {
  return null;
}
